{
  "findings": [
    {
      "check_id": "CKV_AZURE_10",
      "title": "Storage Account Network Rules Default Action is Allow",
      "resource": "azurerm_storage_account_network_rules.notification_storage_rules",
      "severity": "HIGH",
      "explanation": "The default_action is set to 'Allow', which permits access from any network not explicitly denied. This exposes the storage account to potential unauthorized access from the internet or other networks, violating the principle of least privilege."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account_network_rules\" \"notification_storage_rules\" {\n  storage_account_id = azurerm_storage_account.notification_storage.id\n  default_action     = \"Deny\"\n  ip_rules           = [\"127.0.0.1\"]\n  bypass             = [\"Metrics\", \"Logging\"]\n}",
  "fix_summary": "Changed the `default_action` from \"Allow\" to \"Deny\" to ensure that only traffic matching the specified IP rules (or bypasses) is permitted, thereby restricting public exposure of the storage account."
}
